initial_prompt:
Crie um emulador de portas lógicas conforme instruções no JSON abaixo:
{
  "meta_info": {
    "project_name": "LogicGateSim_Web",
    "version": "1.0.0",
    "objective": "Criar um simulador de circuitos digitais interativo, rodando no navegador, capaz de emular portas lógicas básicas e complexas em tempo real.",
    "target_platform": "Web (Navegador Moderno)",
    "tech_stack": {
      "language": "JavaScript (ES6+ Modules)",
      "markup": "HTML5",
      "styling": "CSS3 (CSS Variables para temas)",
      "rendering_engine": "HTML5 Canvas API (para performance) ou SVG (para nitidez) - Recomendado: Canvas",
      "dependencies": "Nenhuma (Vanilla JS puro para máxima portabilidade)"
    }
  },
  "architecture": {
    "pattern": "MVC (Model-View-Controller) modificado para aplicações gráficas",
    "modules": {
      "CanvasManager": "Gerencia o loop de renderização (requestAnimationFrame), zoom, pan e eventos de mouse.",
      "CircuitEngine": "O 'cérebro'. Mantém o estado lógico, a lista de nós (nodes) e conexões (wires). Responsável pela propagação de sinal.",
      "ComponentRegistry": "Fábrica de objetos que define o comportamento e aparência de cada porta lógica (AND, OR, NOT, etc.).",
      "InteractionHandler": "Detecta cliques, arraste (drag & drop) e conexões entre pinos.",
      "UIManager": "Gerencia a barra de ferramentas (toolbar) e sobreposições HTML (modais, configurações)."
    }
  },
  "data_structures": {
    "Node": {
      "id": "UUID string",
      "type": "GATE_AND | GATE_OR | INPUT_SWITCH | etc.",
      "position": { "x": "float", "y": "float" },
      "inputs": "Array de objetos Pin",
      "outputs": "Array de objetos Pin",
      "state": "boolean (High/Low)"
    },
    "Connection": {
      "id": "UUID string",
      "sourceNodeId": "string",
      "sourcePinIndex": "integer",
      "targetNodeId": "string",
      "targetPinIndex": "integer",
      "signalState": "boolean"
    }
  },
  "visual_design": {
    "theme": "Dark Blueprint (Cianotipo Cibernético)",
    "palette": {
      "background": "#1e1e1e",
      "grid_lines": "#2a2a2a",
      "component_body": "#333333",
      "component_border": "#555555",
      "text_color": "#e0e0e0",
      "wire_inactive": "#4a4a4a",
      "wire_active": "#00ff41 (Neon Green)",
      "pin_input": "#ffcc00",
      "pin_output": "#00ccff"
    },
    "style_rules": {
      "wires": "Curvas de Bézier cúbicas para conexões suaves.",
      "gates": "Símbolos padrão IEEE Std 91/91a-1991 (formas distintas) ou Retangulares (IEC) - Preferência: IEEE (Formas clássicas).",
      "feedback": "As conexões ativas devem ter um efeito de 'brilho' (glow) via shadow no Canvas."
    }
  },
  "functional_requirements": {
    "core_logic": {
      "propagation_model": "Event-Driven. Quando a saída de um nó muda, ele notifica os nós conectados para reavaliarem seus inputs.",
      "cycle_detection": "Opcional na v1. Prevenir loops infinitos imediatos (stack overflow) limitando a profundidade da recursão ou usando um 'nextTick'.",
      "components": [
        "AND", "OR", "NOT", "NAND", "NOR", "XOR", "XNOR",
        "Input Switch (Toggle)", "Input Button (Pulse)",
        "Output Lamp/LED", "Clock (Gerador de pulso constante)"
      ]
    },
    "user_interaction": {
      "drag_and_drop": "Usuário arrasta componentes da sidebar para o canvas.",
      "wiring": "Clicar e segurar de um pino de saída para um pino de entrada cria uma conexão.",
      "selection": "Clicar em um componente para selecioná-lo (destaque visual).",
      "deletion": "Tecla 'Delete' ou 'Backspace' remove componentes ou fios selecionados.",
      "panning_zooming": "Roda do mouse para zoom, clique do meio ou espaço+arraste para mover a área de trabalho."
    }
  },
  "step_by_step_implementation_guide": [
    {
      "step": 1,
      "title": "Setup do Ambiente",
      "instruction": "Crie um arquivo index.html com um <canvas> full-screen e um arquivo style.css básico para resetar margens e estilizar a toolbar."
    },
    {
      "step": 2,
      "title": "Engine de Renderização",
      "instruction": "Implemente a classe CanvasManager para desenhar um grid infinito e lidar com o sistema de coordenadas (World Space vs Screen Space)."
    },
    {
      "step": 3,
      "title": "Estrutura de Componentes",
      "instruction": "Crie uma classe base 'Component' que tenha x, y, width, height e métodos draw(). Crie classes filhas para 'LogicGate'."
    },
    {
      "step": 4,
      "title": "Sistema de Fios (Wiring)",
      "instruction": "Implemente a lógica de detectar clique nos pinos (círculos nas bordas dos componentes) e desenhar linhas entre eles."
    },
    {
      "step": 5,
      "title": "Lógica Booleana",
      "instruction": "Implemente a função 'compute()' em cada porta. Ex: AND checa se todos inputs são true. Atualize o estado dos fios baseado nisso."
    }
  ],
  "accessibility_and_ux": {
    "keyboard_shortcuts": {
      "Delete": "Remover seleção",
      "Ctrl+Z": "Desfazer (opcional)",
      "R": "Rotacionar componente (opcional)"
    },
    "responsive": "A barra de ferramentas deve ser colapsável em telas menores."
  }
}

